  'room.hobbies.desc': 'Seus passatempos e projetos criativos.',
  'room.idiomas.desc':
    'Aprenda idiomas: tutor com IA, vocabulário com repetição espaçada, programa por nível e exercícios.',
  'room.calendario.desc': 'Sua agenda: eventos e rotinas por dia, semana e mês.',
  'room.caminos.desc': 'Monte pistas de corrida, trilhos de trem e montanhas-russas no mapa.',
