  'room.ideas.desc':
    'Seu diário de ideias e brainstorms, dez formatos de mapa conceitual em uma tela livre (mapa mental, árvore, linha do tempo, ciclo, pirâmide, Venn…) e oito diagramas para decidir (prós e contras, campo de forças, SWOT, Eisenhower, árvore de decisão, tier list, matriz de decisão ponderada e Ishikawa), à mão ou com IA.',
  'room.metas.desc':
    'O que você se propôs, de toda a casa: a lista de metas com suas submetas e passos, os planos que a IA propõe para cada uma (fases com data que viram submetas de verdade) e o cronograma onde tudo ocupa seu período sobre o eixo do tempo.',
