  'tut.app-computo--formulario.titulo': 'O formulário',
  'tut.app-computo--formulario.resumen':
    'O formulário é o seu livro de fórmulas. Vem com Matemática, Física e Química já prontas, mas não são um catálogo à parte: são fórmulas suas, e você edita, move ou apaga como as que você mesmo escrever.',
