  'ideas.tipo.matriz': 'Matriz de decisão',
  'ideas.tipoDesc.matriz': 'Várias opções pontuadas segundo os critérios que realmente importam para você.',
  'ideas.guia.matriz':
    'Cada critério pesa quanto importa para você (1-5) e cada opção recebe uma nota de 1 a 5 nele. O total multiplica nota por peso, então nada ganha por ser ótimo no que você não liga.',
  'ideas.matriz.criterio': 'Critério',
  'ideas.matriz.opcion': 'Opção',
  'ideas.matriz.peso': 'Peso',
  'ideas.matriz.pesoAyuda': 'Quanto esse critério importa para você (1-5)',
  'ideas.matriz.puntajeAyuda': 'Quão bem ela cumpre (toque para aumentar)',
  'ideas.matriz.total': 'Total',
  'ideas.matriz.nuevoCriterio': 'Novo critério',
  'ideas.matriz.nuevaOpcion': 'Opção',
  'ideas.matriz.criterioN': 'Critério {n}',
  'ideas.matriz.opcionN': 'Opção {n}',
  'ideas.matriz.ayuda':
    'Toque em um nome para mudá-lo, no peso para aumentar o quanto esse critério importa e em cada casa para pontuar de 1 a 5. O total já vem multiplicado pelos pesos.',
  'ideas.ejemplo.ver': 'Ver um exemplo',
  'ideas.ejemplo.chip': 'Exemplo',
  'ideas.ejemplo.comoFunciona': 'Como funciona este formato?',
  'ideas.guia.mental':
    'Um mapa mental abre um tema em todas as direções: a ideia no centro, os ramos grandes ao redor e os detalhes pendurados neles. Serve para esvaziar a cabeça antes de decidir qualquer ordem.',
  'ideas.guia.arbol':
    'A árvore vai do geral ao específico, como um organograma. Use quando o que você tem são categorias que se dividem em subcategorias, e não ideias soltas.',
  'ideas.guia.etimologia':
    'A árvore etimológica desmonta uma palavra: de onde vem, o que significa, como se usa e quais palavras são da sua família. Útil para cavar um conceito antes de um brainstorm ou para dar nome a algo.',
  'ideas.tipo.etimologia': 'Árvore etimológica',
  'ideas.tipoDesc.etimologia': 'Uma palavra desmontada: sua origem, significados, usos e família.',
  'ideas.guia.llaves':
    'As chaves dividem um todo em suas partes, da esquerda para a direita — o esquema clássico. Bom para desmontar algo e ver do que é feito.',
  'ideas.guia.circulo':
    'O círculo põe um tema no centro e o cerca com tudo o que você sabe sobre ele, sem hierarquia. Útil para explorar um conceito ou revisar antes de uma prova.',
  'ideas.guia.flujo':
    'O fluxograma encadeia passos com setas. Toque em um passo e use o botão de forma para transformá-lo em início, decisão ou fim: os losangos são as perguntas de sim/não.',
  'ideas.guia.linea':
    'A linha do tempo ordena por data: cada marco cai alternadamente acima e abaixo da linha, e seus detalhes ficam pendurados para fora. Comece o marco pelo ano e ele se lê sozinho.',
  'ideas.guia.ciclo':
    'O ciclo encadeia etapas que voltam ao começo. Adicione cada etapa a partir da raiz — toque no fundo para que ela não fique presa à anterior — e elas se espalham pelo círculo sozinhas.',
  'ideas.guia.piramide':
    'A pirâmide empilha níveis: cada um se apoia no de baixo, então a base é o que você tem que cobrir primeiro. Toque duas vezes no nome de um nível para mudá-lo.',
  'ideas.guia.venn':
    'O Venn coloca dois conjuntos frente a frente e o que eles têm em comum cai onde se sobrepõem. Escolha a região na barra de baixo antes de adicionar, ou arraste um item sobre outro e ele muda sozinho.',
  'ideas.guia.comparacion':
    'A comparação põe dois temas em colunas e o que compartilham no meio. É o Venn em forma de tabela: mais rápido de ler quando há muitos pontos de cada lado.',
  'ideas.guia.proscontras':
    'Cada ponto pesa de 1 a 5: selecione-o e use − + na barra de baixo. Cada coluna soma no pé, então a decisão deixa de ser “qual lista é mais longa”.',
  'ideas.guia.fuerzas':
    'O campo de forças olha para uma mudança: o que a empurra à esquerda, o que a freia à direita, cada um com seu peso. Se o lado direito ganhar, ataque primeiro a força mais pesada.',
  'ideas.guia.foda':
    'Forças e fraquezas são SUAS; oportunidades e ameaças vêm de fora. Na dúvida, pergunte-se se depende de você ou não.',
  'ideas.guia.eisenhower':
    'Importante em cima, urgente à esquerda. O quadrante “agendar” é o que faz diferença: se ele fica vazio, você passa o dia apagando incêndios.',
  'ideas.guia.decision':
    'Cada ramo é uma opção e dele pendem suas consequências. Anote-as mesmo quando parecerem óbvias: o que não está escrito não se compara com nada.',
  'ideas.guia.tier':
    'S é o melhor e D o pior. O que você ainda não conseguir classificar espera embaixo em “Sem classificar”: arraste até a linha certa quando tiver certeza.',
  'ideas.guia.ishikawa':
    'A cabeça é o problema e cada espinha uma família de causas (método, equipamento, materiais, medição…). Procure CAUSAS, não soluções: essas vêm depois.',
