  'chat.manual.grupo.registrar': 'Registro',
  'chat.manual.intro': 'Abra uma pasta e toque em um exemplo para escrevê-lo no chat. A maioria funciona sem IA.',
  'chat.manual.leyenda.comando': 'azul: o comando',
  'chat.manual.leyenda.ia': 'violeta: gasta uma chamada de IA',
  'chat.manual.leyenda.variable': 'âmbar: mude do seu jeito',
  'chat.manual.nota.biblioteca':
    'Dentro moram o Sábio (chats com IA), que destila tudo em verbetes da wiki e na árvore de temas.',
  'chat.manual.nota.calendario': 'Reúne metas e eventos de todos os apps; seu Cronograma oferece planos com IA (✨).',
  'chat.manual.nota.caminos':
    'Com a pista e a linha de chegada desenhadas, você pode correr contra o relógio ou contra um assistente; o trem se pega nos trilhos.',
  'chat.manual.nota.canchas': 'As quadras se jogam andando dentro delas; você controla a bola ao se aproximar.',
  'chat.manual.nota.cocina':
    'Com IA ela também entende a foto do seu prato (registra estimando os macros). As receitas e dietas que você pedir no chat vêm com imagem: demoram um pouco mais para aparecer e custam os créditos indicados.',
  'chat.manual.nota.cuartos': 'Crie, renomeie e organize cômodos. "Excluir" retira o cômodo da casa.',
  'chat.manual.nota.despacho': 'Com IA você também pode anexar a foto de um recibo: ela registra o gasto.',
  'chat.manual.nota.diario': 'As seções culturais do dia e a entrega do assistente usam IA dentro do app.',
  'chat.manual.nota.ejercicio':
    'Com IA: um plano de treino no seu Cronograma (botão ✨) e imagens ilustrativas dos exercícios dentro do app.',
  'chat.manual.nota.entretenimiento':
    'Jogos de mesa: snake, tetris, xadrez, damas, sudoku, memória, pong, hóquei, simon, lig 4, espaço, dino…',
  'chat.manual.nota.garage':
    'Os veículos que você pilota (bicicleta, moto, carro, OVNI) estão em "Personagem e veículos".',
  'chat.manual.nota.granja':
    'Animais: galinha, porco, cabra, ovelha, vaca e cavalo. Eles comem o que você colhe em Comida.',
  'chat.manual.nota.hobbies': 'No seu Cronograma você pode pedir um plano com IA (✨) para fazer um projeto avançar.',
  'chat.manual.nota.huerto': 'Cultivos: cenoura, alface, girassol, tomate, milho e abóbora.',
  'chat.manual.nota.idiomas':
    'Dentro moram o tutor conversacional por nível, os cartões do chat e os cartões por tema (IA).',
  'chat.manual.nota.configuraciones':
    'Tudo na aba Configurações do editor: idioma, aparência (claro, escuro, transparente), estilo dos ícones, tema e fonte da interface, vidro dos painéis, o estilo visual do mapa (normal, quadrinhos, miniatura, retrô, neon) com seus efeitos, notificações e backup.',
  'chat.manual.aviso.configuraciones':
    'Entrar na conta, restaurar um backup e apagar seus dados NÃO se fazem pelo chat: o assistente abre essa seção para você mesmo confirmar.',
  'chat.manual.nota.interfaz':
    'Tema da casa, fundo do céu, música ambiente e seu resumo Wrapped. Climas musicais: calma, festivo, nocturno, chiptune, acogedor, energia, estudio, arcade, bosque, viaje, carrera, cajita.',
  'chat.manual.nota.mapa': 'Lados: norte, sul, leste e oeste (também acima, abaixo, esquerda ou direita).',
  'chat.manual.nota.memoria':
    'O assistente lembra fatos entre sessões. Anexe uma foto com o clipe ou dite com o microfone; @app força onde a anotação vai.',
  'chat.manual.nota.objetos':
    'Catálogo sem IA: lâmpada, cadeira, mesa, planta, guitarra, tapete, baú, quadro, bola e livro. Qualquer outra coisa é gerada com IA como modelo 3D e salva no seu inventário. Imagens 2D se pedem com "crie uma imagem de…" e ficam no chat.',
  'chat.manual.nota.personaje':
    'Roupas: chapéu, óculos… Partes: cabeça, tronco e pernas. Veículos: bicicleta, moto, carro e OVNI (voa com Espaço/Shift). Vistas: isométrica, terceira e primeira pessoa (tecla V).',
  'chat.manual.nota.sala': 'Com IA, novos lugares são geocodificados sozinhos e aparecem como um pino no mapa-múndi.',
  'chat.manual.nota.superficies':
    'Cores: vermelho, azul, verde… ou um código #hex. Materiais de piso e formas de telhado vêm do catálogo do editor.',
  'chat.manual.nota.teclado':
    'Atalhos para brincar com o teclado. Não se digitam no chat: você os usa na casa. Não fazem nada enquanto você escreve num campo ou com um cômodo aberto.',
  'chat.manual.notaSeccion.apps':
    'Cada app registra seus próprios dados nas suas palavras (use @app para forçar o destino) e seus menus abrem pelo nome. Os exemplos "com IA" sempre gastam uma chamada de IA (plano Pro ou sua chave); seus modelos personalizados também capturam pelo chat e abrem pelo nome. Nota: o interpretador offline fala espanhol, então em inglês a maioria dos comandos passa pela IA.',
  'chat.manual.notaSeccion.mapa': 'Horta, fazenda, pistas e quadras ficam fora dos cômodos, no mapa 3D.',
